-- M2 — Attendance + Shifts + Leave (Brief §5, §6, §15 M2).
-- Kiosk photos: only photo_ref + retention date — never image bytes.
-- NOSI employer rate untouched (still NULL / UNRESOLVED, M0 blocker).
CREATE TYPE shift_template_status AS ENUM ('active','inactive');
CREATE TABLE shift_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), branch_id uuid REFERENCES branches(id), name_ar text NOT NULL, name_en text NOT NULL, start_time text NOT NULL, end_time text NOT NULL, overnight boolean NOT NULL DEFAULT false, unpaid_break_minutes integer NOT NULL DEFAULT 0, status shift_template_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rosters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), branch_id uuid REFERENCES branches(id), week_start text NOT NULL, status text NOT NULL DEFAULT 'draft', published_at timestamptz, published_by_user_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roster_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), roster_id uuid NOT NULL REFERENCES rosters(id), employee_id uuid NOT NULL REFERENCES employees(id), date text NOT NULL, shift_template_id uuid REFERENCES shift_templates(id), on_leave boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attendance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), employee_id uuid NOT NULL REFERENCES employees(id), branch_id uuid REFERENCES branches(id), roster_assignment_id uuid, method text NOT NULL, clock_in_at timestamptz, clock_out_at timestamptz, device_at timestamptz, lat text, lng text, distance_from_branch_m integer, wifi_matched boolean, mock_location_flag boolean NOT NULL DEFAULT false, photo_ref text, verification_status text NOT NULL DEFAULT 'pending_review', source text NOT NULL DEFAULT 'live', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exceptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), attendance_record_id uuid REFERENCES attendance_records(id), employee_id uuid NOT NULL REFERENCES employees(id), branch_id uuid REFERENCES branches(id), kind text NOT NULL, status text NOT NULL DEFAULT 'open', reason text NOT NULL, resolved_by_user_id uuid, resolution_note text, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE leave_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), employee_id uuid NOT NULL REFERENCES employees(id), type text NOT NULL, start_date text NOT NULL, end_date text NOT NULL, days text NOT NULL, status text NOT NULL DEFAULT 'pending', reason text, decided_by_user_id uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE leave_balances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), employee_id uuid NOT NULL REFERENCES employees(id), year integer NOT NULL, type text NOT NULL, entitlement_days text NOT NULL, carried_days text NOT NULL DEFAULT '0', taken_days text NOT NULL DEFAULT '0');
CREATE TABLE kiosk_consents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), employee_id uuid NOT NULL REFERENCES employees(id), consented boolean NOT NULL DEFAULT false, notice_shown_at timestamptz, consented_at timestamptz, retention_days integer NOT NULL DEFAULT 90);
CREATE TABLE kiosk_passcodes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), employee_id uuid NOT NULL REFERENCES employees(id), passcode_hash text NOT NULL, failed_attempts integer NOT NULL DEFAULT 0, locked_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE swap_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), roster_assignment_id uuid NOT NULL REFERENCES roster_assignments(id), requester_employee_id uuid NOT NULL REFERENCES employees(id), cover_employee_id uuid NOT NULL REFERENCES employees(id), status text NOT NULL DEFAULT 'pending', decided_by_user_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE open_shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), roster_assignment_id uuid REFERENCES roster_assignments(id), branch_id uuid REFERENCES branches(id), date text NOT NULL, shift_template_id uuid REFERENCES shift_templates(id), status text NOT NULL DEFAULT 'open', filled_by_employee_id uuid, claimed_by_employee_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), to_phone text NOT NULL, template text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'queued_stubbed', provider text NOT NULL DEFAULT 'stub', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_attendance_tenant_employee ON attendance_records(tenant_id, employee_id);
CREATE INDEX idx_exceptions_tenant_status ON exceptions(tenant_id, status);
CREATE INDEX idx_roster_assignments_roster ON roster_assignments(roster_id);
CREATE INDEX idx_leave_tenant_employee ON leave_requests(tenant_id, employee_id);
CREATE INDEX idx_outbox_tenant ON outbox_messages(tenant_id);
